volatile uint8_t trigger_pending = 0;

volatile uint8_t check_arming_atomically(void) {
    uint8_t current_armed = armed_flag;  // Copy to local instantly
    return current_armed;                // Never block here
}

ISR(PCINT0_vect) {  // Pin capture ISR runs <5 cycles
